["<HTML>\n<BODY>\n<H1 align=\"center\">HORDE MILITARY RANKS</H1><BR/>\n<P align=\"center\">OFFICERS</P><BR/>\n<P align=\"center\">High Warlord</P>\n<P align=\"center\">Warlord</P>\n<P align=\"center\">General</P>\n<P align=\"center\">Lieutenant General</P>\n<P align=\"center\">Champion</P>\n<P align=\"center\">Centurion</P>\n<P align=\"center\">Legionnaire</P>\n<P align=\"center\">Blood Guard</P>\n<P align=\"center\">Stone Guard</P><BR/>\n<P align=\"center\">ENLISTED</P><BR/>\n<P align=\"center\">First Sergeant</P>\n<P align=\"center\">Senior Sergeant</P>\n<P align=\"center\">Sergeant</P>\n<P align=\"center\">Grunt</P>\n<P align=\"center\">Scout</P>\n</BODY>\n</HTML>"]="<HTML>\n<BODY>\n<H1 align=\"center\">호드 군사계급</H1><BR/>\n<P align=\"center\">장교 계급</P><BR/>\n<P align=\"center\">대장군</P>\n<P align=\"center\">장군</P>\n<P align=\"center\">전투사령관</P>\n<P align=\"center\">사령관</P>\n<P align=\"center\">부사령관</P>\n<P align=\"center\">백인대장</P>\n<P align=\"center\">용사</P>\n<P align=\"center\">혈투사</P>\n<P align=\"center\">투사</P><BR/>\n<P align=\"center\">사병 계급</P><BR/>\n<P align=\"center\">하급투사</P>\n<P align=\"center\">정예수호병</P>\n<P align=\"center\">수호병</P>\n<P align=\"center\">그런트</P>\n<P align=\"center\">척후병</P><BR/>\n</BODY>\n</HTML>",
["<HTML>\n<BODY>\n<H1 align=\"center\">MILITARY RANKS OF THE HORDE &amp; ALLIANCE</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRankHorde\" align=\"left\"/>\n<BR/>\n<P align=\"right\">Throm'ka!  In this</P>\n<P align=\"right\">book you will find</P>\n<P align=\"right\">many listings of</P>\n<P align=\"right\">the military ranks</P>\n<P align=\"right\">of the Horde and</P>\n<P align=\"right\">the puny Alliance.</P>\n<P align=\"right\">First will come the</P>\n<P align=\"right\">Horde, then the Alliance,</P>\n<P align=\"right\">each with listings of officers and enlisted ranks.  As is fitting, the strongest are listed at the top, with the weaker listed below them.</P>\n</BODY>\n</HTML>"]="<HTML>\n<BODY>\n<H1 align=\"center\">호드와 얼라이언스의 군사계급 </H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRankHorde\" align=\"left\"/>\n<BR/>\n<P align=\"right\">트롬카! 이 책에는</P>\n<P align=\"right\">위대한 호드와</P>\n<P align=\"right\">나약한 얼라이언스의</P>\n<P align=\"right\">군사 계급이</P>\n<P align=\"right\">정리되어 있다.</P>\n<P align=\"right\">먼저 호드의 군사 계급을,</P>\n<P align=\"right\">그 다음에 얼라이언스의 계급을 기록했으며</P>\n<P align=\"right\">각각 장교와 사병 계급으로 구분되어 있다. 가장 높</P>\n<P align=\"right\">은 계급이 제일 위에! 아래에 낮은 계급이 온다!</P>\n</BODY>\n</HTML>",
["<HTML>\n<BODY>\n<H1 align=\"center\">OFFICER RANKS OF THE ALLIANCE</H1><BR/>\n<P align=\"center\">Part 1</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">Grand Marshal</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">Field Marshal</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">Marshal</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">Commander</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">Lieutenant Commander</P><BR/><BR/>\n</BODY>\n</HTML>"]="<HTML>\n<BODY>\n<H1 align=\"center\">얼라이언스 장교 계급</H1><BR/>\n<P align=\"center\">제 1 장</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">최고사령관</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">야전사령관</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">작전사령관</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">사령관</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">부사령관</P><BR/><BR/>\n</BODY>\n</HTML>",
["<HTML>\n<BODY>\n<H1 align=\"center\">OFFICER RANKS OF THE HORDE</H1><BR/>\n<P align=\"center\">Part 1</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">High Warlord</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">Warlord</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">General</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">Lieutenant General</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">Champion</P><BR/><BR/>\n</BODY>\n</HTML>"]="<HTML>\n<BODY>\n<H1 align=\"center\">호드 장교 계급</H1><BR/>\n<P align=\"center\">제 1 장</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">대장군</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">장군</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">전투사령관</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">사령관</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">부사령관</P><BR/><BR/>\n</BODY>\n</HTML>",
["<HTML> <BODY> <BR/> <BR/> <H1 align=\"center\"> Eliza </H1> <BR/> <BR/> <BR/> <BR/> <P align=\"center\"> Beloved wife, may the earth sate your hunger. </P> </BODY> </HTML>"]="<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align=\"center\">\n엘리자\n</H1>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"center\">\n사랑하는 아내여, 대지가 그대의 굶주림을 달래 주기를.\n</P>\n</BODY>\n</HTML>",
["<HTML> <BODY> <H1 align=\"center\"> CRYSTAL PYLON USER'S MANUAL </H1> <BR/> <P align=\"center\"> \"A guide to collecting and using the power crystals of Un'Goro Crater\" </P> <BR/> <BR/> <P align=\"left\">Chapter 1: The Northern Pylon </P> <BR/> <P align=\"left\">Chapter 2: The Eastern Pylon </P> <BR/> <P align=\"left\">Chapter 3: The Western Pylon </P> <BR/> </BODY> </HTML."]="<HTML>\n<BODY>\n<H1 align=\"center\">\n수정탑 사용자 설명서\n</H1>\n<BR/>\n<P align=\"center\">\n\"운고로 분화구의 수정 동력 수집 및 사용 안내\"\n</P>\n<BR/>\n<BR/>\n<P align=\"left\">\n제1장: 북쪽 수정탑\n</P>\n<BR/>\n<P align=\"left\">\n제2장: 동쪽 수정탑\n</P>\n<BR/>\n<P align=\"left\">\n제3장: 서쪽 수정탑\n</P>\n<BR/>\n</BODY>\n</HTML>",
